/// How a set is obtained.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Acquire {
    /// Every character owns it from the start.
    Starter,
    /// The ending clear at this difficulty (0 노말 · 1 하드코어 · 2 헬) — the byte the 2회차
    /// transition found (`wie_util::stats::ending_transition`).
    Clear(u8),
}

/// ★ 168차: the hero a set is made for (`CHAR+0xb8`, `items::char_hero`) — such a set is offered
